import {STATUS,SITE,siteType,safeUrl,phoneNumber} from './core.mjs';

export function showDetail({state,id,updateLeads,toast,icon,esc,date,contactLinks}){
  const l=state.leads.find(x=>x.id===id);if(!l)return;
  const dialog=document.querySelector('#detail');
  const events=state.events.filter(e=>e.company_id===id);
  const localDate=l.follow_up_at?new Date(new Date(l.follow_up_at).getTime()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):'';
  dialog.innerHTML=`<div class="modal-header"><div><h2 id="detail-title">Detalhes do lead</h2><p>Dados da empresa e acompanhamento comercial</p></div><button class="icon-button" data-close aria-label="Fechar">${icon('close')}</button></div><div class="modal-body"><div class="detail-head"><span class="lead-avatar">${esc(l.name.split(' ').filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase())}</span><div><h2>${esc(l.name)}</h2><p>${esc(l.category||'Categoria não informada')} · ${esc(l.city||'Cidade não informada')}</p></div></div><div class="detail-links">${contactLinks(l)}</div><dl class="info-list"><dt>Endereço</dt><dd>${esc(l.address||'Não informado')}</dd><dt>Telefone</dt><dd>${esc(l.phone||'Não informado')}</dd><dt>Site</dt><dd>${SITE[siteType(l.website)]}${safeUrl(l.website)?` · <a href="${esc(safeUrl(l.website))}" target="_blank" rel="noopener noreferrer">abrir link</a>`:''}</dd><dt>Google</dt><dd>${l.rating??'—'} · ${(l.reviews||0).toLocaleString('pt-BR')} avaliações</dd><dt>E-mail</dt><dd>${esc(l.email||'Não informado')}</dd></dl><hr class="divider"><form id="lead-form"><div class="form-grid"><div class="field"><label for="detail-status">Área do lead</label><select id="detail-status">${Object.entries(STATUS).map(([k,v])=>`<option value="${k}" ${l.status===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="detail-date">Próximo contato</label><input id="detail-date" type="datetime-local" value="${esc(localDate)}"></div></div><div class="field"><label for="detail-notes">Notas</label><textarea id="detail-notes" placeholder="O que foi conversado? Qual é o próximo passo?">${esc(l.notes||'')}</textarea></div><div class="form-actions"><button class="primary" type="submit">Salvar acompanhamento</button>${phoneNumber(l.phone)?`<a href="https://wa.me/${phoneNumber(l.phone)}" target="_blank" rel="noopener noreferrer"><button type="button">${icon('message')}Abrir WhatsApp</button></a>`:''}</div></form><hr class="divider"><h3>Histórico</h3><ul class="timeline">${events.length?events.map(e=>`<li>${esc(e.description||'Lead atualizado')}${e.to_status?` · ${esc(STATUS[e.to_status]||e.to_status)}`:''}<small>${date(e.created_at)}</small></li>`).join(''):`<li>Lead adicionado à base<small>${date(l.created_at)}</small></li>`}</ul></div>`;
  dialog.showModal();dialog.querySelector('[data-close]').onclick=()=>dialog.close();
  dialog.querySelector('#lead-form').onsubmit=async e=>{e.preventDefault();const status=dialog.querySelector('#detail-status').value;const value=dialog.querySelector('#detail-date').value;const follow_up_at=value?new Date(value).toISOString():null;if(status==='followup'&&!follow_up_at){toast('Escolha a data do próximo contato para colocar em Follow-up.');dialog.querySelector('#detail-date').focus();return;}const btn=e.submitter;btn.disabled=true;try{await updateLeads([id],{status,follow_up_at,notes:dialog.querySelector('#detail-notes').value.trim()});dialog.close();}catch(err){toast(err.message);}finally{btn.disabled=false;}};
}
